function dateLabel(createdAt: string): string { return createdAt; }
const ticket = { id: 42, createdAt: "2026-10-01T09:30:00Z" };
console.log(dateLabel(ticket.createdAt)); // 2026-10-01T09:30:00Z

function isOpen(status: string): boolean { return status === "OPEN"; }
console.log(isOpen("OPEN")); // true
console.log(isOpen("CLOSED")); // false

function formatTicket(ticket) {
  return `#${ticket.id} ${ticket.title}`;
}
console.log(formatTicket({ id: 1, title: "API" })); // #1 API

