type TicketPreview = { id: number; title: string; createdAt: string };
function formatTicket(ticket: TicketPreview): string {
  return `#${ticket.id} ${ticket.title} — ${ticket.createdAt}`;
}
console.log(formatTicket({ id: 42, title: "Eksport", createdAt: "2026-10-01" }));
